                        .family(egui::FontFamily::Monospace),
                );
                ui.label(theme::meta_text(
                    ui,
                    format!("Key {}", short_hash(&identity.spki_sha256)),
                ));
                if !address.is_empty() {
                    ui.label(theme::meta_text(ui, format!("Address {address}")));
                }
                ui.label(theme::meta_text(
                    ui,
                    format!(
                        "Scan, or type the key and the code. Grants {} scope. Open for five minutes or three wrong codes.",
                        window.scope.word()
                    ),
                ));
                ui.horizontal(|ui| {
                    // The QR's text, for a client without a camera (the
                    // command-line browser takes it as one argument).
                    if theme::secondary(ui, "Copy invite")
                        .on_hover_text("The QR code's text, to paste into a client")
