        404 => "Not Found",
        405 => "Method Not Allowed",
        413 => "Content Too Large",
        429 => "Too Many Requests",
        503 => "Service Unavailable",
        504 => "Gateway Timeout",
        _ => "Error",
    }
}

/// Write one JSON response. Head and body in one write, so a reply is
/// one TLS record and one segment. Every reply says it is not to be
/// cached and not to be sniffed, which no native client reads and a
/// browser does; the reply's own headers follow.
fn respond<W: Write>(w: &mut W, reply: &RemoteReply) -> io::Result<()> {
    let mut out = format!(
        "HTTP/1.1 {} {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: keep-alive\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n",
        reply.status,
        reason(reply.status),
        reply.body.len()
    );
    for (name, value) in &reply.headers {
        let _ = write!(out, "{name}: {value}\r\n");
    }
    out.push_str("\r\n");
    let mut out = out.into_bytes();
    out.extend_from_slice(&reply.body);
    w.write_all(&out)?;
    w.flush()
}

/// Write one of the web page's files, with the policy headers that keep
/// the page to itself, and close: a page load is a burst of short
/// requests from a stranger, and a kept connection would hold one of
/// the unauthenticated pool's four slots for the idle timeout.
fn respond_page<W: Write>(w: &mut W, page: &web::Page) -> io::Result<()> {
    let mut out = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: {}\r\nContent-Length: {}\r\nConnection: close\r\n",
        page.content_type,
        page.body.len()
    );
    for (name, value) in web::HEADERS {
        let _ = write!(out, "{name}: {value}\r\n");
    }
    out.push_str("\r\n");
    let mut out = out.into_bytes();
    out.extend_from_slice(page.body.as_bytes());
    w.write_all(&out)?;
    w.flush()
}

/// The error reply the connection thread sends for what never reaches
/// the frame.
fn error_reply(status: u16, code: &str, message: &str) -> RemoteReply {
    let body = serde_json::json!({ "error": { "code": code, "message": message } })
        .to_string()
        .into_bytes();
    RemoteReply::new(status, body, false)
}

