use std::net::IpAddr;
use std::time::SystemTime;

use uuid::Uuid;

use super::action::PairingWindow;
use super::action::{AppAction, AppCore, Clock, Effect, Out, PAIRING_ATTEMPTS, PAIRING_WINDOW};
use crate::ports::remote::{Identity, PairedDevice, Scope};

/// A device's last-seen time is saved when it moved by at least this
/// much, so a polling device does not rewrite `devices.json` on every
/// request.
const LAST_SEEN_SAVE_INTERVAL_SECS: u64 = 300;

/// The pairing invite as the QR code and "Copy invite" carry it: the
/// page's URL with the code, the key hash and the server id in the
/// fragment. A fragment is never part of a request, so a server the
/// owner has not verified never receives the code; the page compares
/// the key and the id with `/info` before it sends anything. `address`
/// is the machine's local-network address, used only while the port
/// listens on the network; a Mac-only port is reached at loopback.
#[must_use]
pub fn invite_url(
    identity: &Identity,
    window: &PairingWindow,
    address: Option<IpAddr>,
    port: u16,
) -> String {
    let host = match address.filter(|_| identity.listen.lan) {
        Some(IpAddr::V6(ip)) => format!("[{ip}]"),
        Some(ip) => ip.to_string(),
        None => "127.0.0.1".to_owned(),
    };
    format!(
        "https://{host}:{port}/#code={}&key={}&id={}",
        window.code, identity.spki_sha256, identity.server_id
    )
}

