/// A write authenticated by the cookie alone must come from the page's
/// own origin (`https://` and the `Host` header): without an `Origin`
/// or with another, 403 `origin`; a `GET` needs none; a bearer request
/// needs none; and the same holds for the upgrade to the events socket.
#[test]
fn a_cookie_write_needs_the_pages_origin_and_a_bearer_needs_none() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let cookie = pair_by_cookie(&mut port, "ABCD2345", Scope::Control, "Chrome on Android");
    let token = pair(&mut port, "BCDE3456", Scope::Control, "Pad");
    let send = format!("/api/v1/sessions/{session}/send");
    let c = cookie.pair();
    let body = |op: &str| serde_json::json!({ "op": op, "text": "hello" }).to_string();
    let r = call_with(&mut port, "POST", &send, &[("Cookie", &c)], &body("o1"));
    assert_eq!((r.status, code(&r.json())), (403, "origin"), "{}", r.body);
    let other_port = [("Cookie", c.as_str()), ("Origin", "https://localhost:1")];
    let r = call_with(&mut port, "POST", &send, &other_port, &body("o1"));
    assert_eq!((r.status, code(&r.json())), (403, "origin"), "{}", r.body);
    let elsewhere = [("Cookie", c.as_str()), ("Origin", "https://evil.example")];
    let r = call_with(&mut port, "POST", &send, &elsewhere, &body("o1"));
    assert_eq!((r.status, code(&r.json())), (403, "origin"), "{}", r.body);
    let own = [("Cookie", c.as_str()), ("Origin", "https://localhost")];
    let r = call_with(&mut port, "POST", &send, &own, &body("o1"));
    assert_ne!(code(&r.json()), "origin", "{}", r.body);
    assert_ne!(r.status, 403, "{}", r.body);
    let r = call_with(&mut port, "GET", "/api/v1/waiting", &[("Cookie", &c)], "");
    assert_eq!(r.status, 200, "a read needs no Origin: {}", r.body);
    let (status, reply) = call(&mut port, "POST", &send, Some(&token), &body("o2"));
    assert_ne!(code(&reply), "origin", "{status} {reply}");
    assert_ne!(status, 403, "{reply}");

    let foreign = subscribe_with(
        &mut port,
        vec![
            ("Cookie".into(), c.clone()),
            ("Origin".into(), "https://evil.example".into()),
        ],
        "/api/v1/events",
    );
    assert!(foreign.is_err(), "a foreign upgrade is refused");
    let bare = subscribe_with(&mut port, vec![("Cookie".into(), c.clone())], "/api/v1/events");
    assert!(bare.is_err(), "an upgrade with no Origin is refused");
    let own = subscribe_with(
        &mut port,
        vec![
            ("Cookie".into(), c),
            ("Origin".into(), "https://localhost".into()),
        ],
        "/api/v1/events",
    );
    assert!(own.is_ok(), "{:?}", own.err());
    assert_eq!(port.app.subscriber_count(), 1);
}

/// `/me` says the device's scope as the dialog sets it; after Revoke
/// the cookie is the same 401 as an unknown token and `/info` still
/// names the same host, which is what lets the page say "removed".
#[test]
fn me_follows_the_scope_and_a_revoked_cookie_is_refused_while_info_is_unchanged() {
    let mut port = port();
    let cookie = pair_by_cookie(&mut port, "ABCD2345", Scope::Read, "Safari on iPad");
    let (_, before) = get(&mut port, "/api/v1/info", None);
    let c = cookie.pair();
    let r = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &c)], "");
    assert_eq!(r.json()["body"]["scope"], "read");
    let device = port.app.core().devices()[0].id;
    port.app.dispatch(AppAction::SetDeviceScope {
        device,
        scope: Scope::Control,
    });
    let r = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &c)], "");
    assert_eq!(r.json()["body"]["scope"], "control");
    port.app.dispatch(AppAction::RevokeDevice(device));
    let r = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &c)], "");
    assert_eq!((r.status, code(&r.json())), (401, "unauthorized"));
    let (_, after) = get(&mut port, "/api/v1/info", None);
    assert_eq!(after["body"]["server_id"], before["body"]["server_id"]);
    assert_eq!(after["body"]["spki_sha256"], before["body"]["spki_sha256"]);
}

/// A page reply closes its connection, so loads in a row never hold
/// the pool; five at once against a pool of four are measured; and the
/// page has a window of its own, 120 a minute, which leaves `/info` and
/// `/pair` theirs.
#[test]
fn page_loads_free_their_slot_and_have_their_own_window() {
    let port = port();
    for _ in 0..=MAX_UNAUTHENTICATED {
        let r = http_with(port.addr, &port.client, "GET", "/app.css", &[], "").unwrap();
        assert_eq!(r.status, 200);
    }
    let served = (0..5)
        .map(|_| {
            let addr = port.addr;
            let config = Arc::clone(&port.client);
            std::thread::spawn(move || {
                http_with(addr, &config, "GET", "/app.js", &[], "").is_ok_and(|r| r.status == 200)
            })
        })
        .collect::<Vec<_>>()
        .into_iter()
        .filter(|t| t.join().unwrap())
        .count();
    eprintln!("parallel page requests served: {served} of 5 against a pool of 4");
    assert!(served >= MAX_UNAUTHENTICATED, "{served}");
    drop(port);

    let mut port = port();
    for n in 0..PAGE_PER_MINUTE {
        let r = http_with(port.addr, &port.client, "GET", "/", &[], "").unwrap();
        assert_eq!(r.status, 200, "page request {n}");
    }
    let r = http_with(port.addr, &port.client, "GET", "/app.js", &[], "").unwrap();
    assert_eq!((r.status, code(&r.json())), (429, "rate_limited"));
    let (status, _) = get(&mut port, "/api/v1/info", None);
    assert_eq!(status, 200, "info has its own window");
    let (status, reply) = call(&mut port, "POST", "/api/v1/pair", None, "{}");
    assert_eq!((status, code(&reply)), (403, "pairing_closed"), "pair has its own window");
}

